// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.intentimport com.roshan.persona.common.CorrelationId/** * NOUS — Intent classification result. * * Output of Layer 0 (IntentClassifier). Contains the classified [intent], * calibrated [confidence] (0.0-1.0 via Platt scaling), which [extractor] * matched, and timing metadata. * * @see <a href="docs/spec/module2-spec-review.pdf">§4 Layer 0 + §4.2 Platt Scaling</a> */data class IntentClassification(    val intent: Intent,    /** Calibrated confidence (0.0-1.0). Below 0.5 → Unknown; 0.5-0.85 → defer with hint. */    val confidence: Float,    /** Which classifier matched. */    val extractor: ExtractorType,    /** Slots extracted (entity → value). May be empty for binary intents (e.g., TorchOn). */    val extractedSlots: Map<String, String>,    /** Wall-clock duration of classification (nanoseconds). */    val durationNanos: Long,    /** Correlation ID for tracing. */    val correlationId: CorrelationId,    /** Whether NER (Stage 4) was invoked (false = regex-only slot extraction). */    val usedNer: Boolean,    /** Whether compound detection (Stage 5) split the input. */    val isCompound: Boolean,) {    /** Whether the classification should defer to next layer. */    val shouldDefer: Boolean        get() = confidence < CONFIDENCE_THRESHOLD_HIGH    /** Whether the classification is the final answer (high confidence). */    val isFinal: Boolean        get() = confidence >= CONFIDENCE_THRESHOLD_HIGH && intent !is Intent.Unknown    companion object {        /** Above this → return intent. */        const val CONFIDENCE_THRESHOLD_HIGH = 0.85f        /** Below this → Intent.Unknown. */        const val CONFIDENCE_THRESHOLD_LOW = 0.5f    }}/** * Which extractor matched. * * Order of reliability (high → low): *   REGEX > NER > KEYWORD > EMBEDDING * * @see <a href="docs/spec/module2-spec-review.pdf">§4.2 Platt Scaling</a> */enum class ExtractorType {    /** Pre-compiled regex pattern (most reliable). */    REGEX,    /** BERT-tiny NER model (for contact names, locations, etc.). */    NER,    /** Keyword + token match. */    KEYWORD,    /** Sentence embedding cosine similarity (least reliable). */    EMBEDDING,    /** Composite — multiple extractors agreed. */    COMPOSITE,}